#!/usr/bin/env bash
# Re-run every long-form dev method with prompts v2 (deviation D3). Generations are cache hits; only decomposition,
# scoring and repair are recomputed. Do NOT edit this file while it runs.
set -uo pipefail
cd "$(dirname "$0")/.."
M="$1"
for d in asqa bio; do
  echo "##### $d longform $(date -u +%FT%TZ)"
  bash scripts/py.sh scripts/run_longform.py --dataset "$d" --split dev --model "$M" --verifier-device cpu 2>&1 | grep --line-buffered -E '^\{|^seconds|^wrote|Error|Traceback|stage .* done' | cut -c1-1100
  for v in closed_book rag_verify; do
    echo "##### $d cove-$v"
    bash scripts/py.sh scripts/run_cove.py --dataset "$d" --split dev --variant "$v" --model "$M" 2>&1 | grep -E '^\{|^wrote|Error' | cut -c1-600
  done
  for s in run_rarr run_flare; do
    echo "##### $d $s"
    bash scripts/py.sh scripts/$s.py --dataset "$d" --split dev --model "$M" 2>&1 | grep -E '^\{|^wrote|Error' | cut -c1-600
  done
done
echo LONGFORM_V2_END
